   version=subprocess.check_output(['prometheus','--version'],stderr=subprocess.STDOUT,text=True,timeout=3);assert 'version 3.5.' in version
   self.proc=subprocess.Popen(['prometheus','--config.file='+str(self.path),'--storage.tsdb.path='+str(self.root/'data'),'--storage.tsdb.retention.time=1h','--storage.tsdb.wal-segment-size=10MB','--query.max-concurrency=2','--web.listen-address=127.0.0.1:'+str(self.port),'--web.enable-lifecycle','--rules.alert.resend-delay=500ms','--log.level=error'],stdout=self.log,stderr=self.log,env={**os.environ,'GOMAXPROCS':'2','GOMEMLIMIT':'96MiB'})
   self.wait(lambda:self.request('/-/ready') is not None,'HTTP ready');return self
  except BaseException:self.__exit__(None,None,None);raise
 def write(self):self.path.write_text(yaml.safe_dump(self.config,sort_keys=False),encoding='utf8')
 def request(self,path,post=False):
  opener=urllib.request.build_opener(urllib.request.ProxyHandler({}));req=urllib.request.Request(self.base+path,data=b'' if post else None)
  with opener.open(req,timeout=1) as response:
   data=response.read();return json.loads(data) if 'json' in response.headers.get('Content-Type','') else data
 def wait(self,fn,label,seconds=8):
  end=time.monotonic()+seconds
  while time.monotonic()<end:
   assert self.proc.poll() is None,'Prometheus exited: '+(self.root/'server.log').read_text(errors='replace')[-1800:]
   try:
    value=fn()
    if value is not False and value is not None:return value
   except (OSError,urllib.error.URLError):pass
   time.sleep(.03)
